// pubspec.yaml: webview_flutter: ^4.7.0
import 'package:webview_flutter/webview_flutter.dart';
import 'package:webview_flutter_android/webview_flutter_android.dart';
import 'package:webview_flutter_wkwebview/webview_flutter_wkwebview.dart';

class HelpWebView extends StatefulWidget {
  const HelpWebView({super.key, required this.url});
  final String url;
  @override State<HelpWebView> createState() => _HelpWebViewState();
}

class _HelpWebViewState extends State<HelpWebView> {
  late final WebViewController _controller;
  double _progress = 0;

  @override
  void initState() {
    super.initState();
    // Platform-specific params
    final params = WebViewPlatform.instance is WebKitWebViewPlatform
        ? WebKitWebViewControllerCreationParams(
            allowsInlineMediaPlayback: true,
            mediaTypesRequiringUserAction: const {PlaybackMediaTypes.audio},
          )
        : const PlatformWebViewControllerCreationParams();

    _controller = WebViewController.fromPlatformCreationParams(params)
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setBackgroundColor(Colors.white)
      ..setNavigationDelegate(NavigationDelegate(
        onProgress: (p) => setState(() => _progress = p / 100),
        onNavigationRequest: (r) {
          // Redirect external URLs to the system browser (better UX)
          if (!r.url.startsWith('https://help.mysite.com')) {
            launchUrl(Uri.parse(r.url), mode: LaunchMode.externalApplication);
            return NavigationDecision.prevent;
          }
          return NavigationDecision.navigate;
        },
        onWebResourceError: (e) => print('web error: ${e.description}'),
      ))
      ..addJavaScriptChannel('Flutter', onMessageReceived: (msg) {
        // JS did: Flutter.postMessage('close')
        if (msg.message == 'close') Navigator.of(context).pop();
      })
      ..loadRequest(Uri.parse(widget.url));

    // Android-specific: enable mixed content only if truly needed
    if (_controller.platform is AndroidWebViewController) {
      (_controller.platform as AndroidWebViewController)
          .setMediaPlaybackRequiresUserGesture(false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Help'),
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(2),
          child: LinearProgressIndicator(value: _progress),
        ),
      ),
      body: WebViewWidget(controller: _controller),
    );
  }
}

// ────── Dart → JS: run script on demand ──────
_controller.runJavaScript('document.body.style.background = "lightyellow"');

// ────── Post a message to JS ──────
_controller.runJavaScript('window.dispatchEvent(new CustomEvent("themeChanged", {detail: "dark"}))');
